var ENT=[["Scrubber", "Signature Scrubber pillar of the Transformation Audit Logger framework."], ["Deduper", "Signature Deduper pillar of the Transformation Audit Logger framework."], ["Imputer", "Signature Imputer pillar of the Transformation Audit Logger framework."], ["Outlier Scout", "Signature Outlier Scout pillar of the Transformation Audit Logger framework."], ["Normalizer", "Signature Normalizer pillar of the Transformation Audit Logger framework."], ["Coercer", "Signature Coercer pillar of the Transformation Audit Logger framework."], ["Canonicalizer", "Signature Canonicalizer pillar of the Transformation Audit Logger framework."]];
